import{R as e,e as o,f as i,U as n}from"./chunks/framework.ywem4qy5.js";const m=JSON.parse('{"title":"Agile CRM","description":"","frontmatter":{},"headers":[],"relativePath":"integrations/crm/agile-crm.md","filePath":"integrations/crm/agile-crm.md","lastUpdated":1775908585000}'),a={name:"integrations/crm/agile-crm.md"};function r(l,t,s,g,c,h){return o(),i("div",null,[...t[0]||(t[0]=[n('<h1 id="agile-crm" tabindex="-1">Agile CRM <a class="header-anchor" href="#agile-crm" aria-label="Permalink to &quot;Agile CRM&quot;">​</a></h1><p>Follow the below steps to connect to the Agile CRM API.</p><h3 id="step-1-create-the-integration" tabindex="-1">Step 1. Create the Integration <a class="header-anchor" href="#step-1-create-the-integration" aria-label="Permalink to &quot;Step 1. Create the Integration&quot;">​</a></h3><ol><li>Navigate to <strong>Formie</strong> → <strong>Settings</strong> → <strong>CRM</strong>.</li><li>Click the <strong>New Integration</strong> button.</li><li>Select Agile CRM as the <strong>Integration Provider</strong>.</li></ol><h3 id="step-2-connect-to-the-agile-crm-api" tabindex="-1">Step 2. Connect to the Agile CRM API <a class="header-anchor" href="#step-2-connect-to-the-agile-crm-api" aria-label="Permalink to &quot;Step 2. Connect to the Agile CRM API&quot;">​</a></h3><ol><li>Go to <a href="https://www.agilecrm.com/" target="_blank">Agile CRM</a> and login to your account.</li><li>Click on your profile dropdown on the top-right of the screen, and select <strong>Admin Settings</strong>.</li><li>Click on the <strong>Developers &amp; API</strong> menu in the left-hand sidebar.</li><li>Copy the <strong>REST API</strong> from Agile CRM and paste in the <strong>API Key</strong> field in Formie.</li><li>Enter the email for your Agile CRM account in the <strong>API Email</strong> field in Formie.</li><li>Enter the full domain (including <code>https://</code>) for your Agile CRM account in the <strong>Domain</strong> field in Formie.</li></ol><h3 id="step-3-test-connection" tabindex="-1">Step 3. Test Connection <a class="header-anchor" href="#step-3-test-connection" aria-label="Permalink to &quot;Step 3. Test Connection&quot;">​</a></h3><ol><li>Save this integration.</li><li>Click on the <strong>Refresh</strong> button in the right-hand sidebar.</li></ol><h3 id="step-4-form-setting" tabindex="-1">Step 4. Form Setting <a class="header-anchor" href="#step-4-form-setting" aria-label="Permalink to &quot;Step 4. Form Setting&quot;">​</a></h3><ol><li>Go to the form you want to enable this integration on.</li><li>Click the <strong>Integrations</strong> tab.</li><li>In the left-hand sidebar, select the name you gave the integration.</li><li>Enable the integration and fill out all required fields.</li><li>Click <strong>Save</strong> to save the form.</li></ol>',10)])])}const p=e(a,[["render",r]]);export{m as __pageData,p as default};
